  IF (SELECT short_description FROM public.skills WHERE id = 'objections.regla_no') IS DISTINCT FROM $v$Dos no seguidos y te vas, en toda la visita, también en el cierre. Tienen que ser consecutivos. «Lo voy a pensar» es una objeción, no un no.$v$ THEN RAISE EXCEPTION 'la habilidad objections.regla_no no quedó'; END IF;
